patch.value:
if T == INT:
  t_cnt = count_trailing_zeros_or_ones(V) & 0x3F
  l_cnt = count_leading_zeros_or_ones(V) & 0x3F
  val_6 = V & 0x3F
  res = t_cnt ^ (l_cnt << 3) ^ (val_6 << 6)
  return res
else if T == FP:
  class = classify_fp(V)
  if class == FP64:
    res = (sign(V) << 11) | (exp_FP64(V)[7:0] << 3)
    return res
  else if class == FP32:
    res = (sign(V) << 8) | (exp_FP32(V)[4:0] << 3)
    return res
  else if class == FP16:
    res = (sign(V) << 5) | (exp_FP16(V)[1:0] << 3)
    return res
else if T == FLAG:
  res = (V[3:0] << 8) | (V[3:0] << 4) | V[3:0]
  return res
